package com.kangli.qms.api.qualitysystem;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.kangli.qms.common.*; import com.kangli.qms.domain.qualitysystem.entity.*; import com.kangli.qms.domain.qualitysystem.mapper.*; import com.kangli.qms.domain.measurement.entity.*; import com.kangli.qms.domain.measurement.mapper.*; import com.kangli.qms.domain.exception.entity.ExceptionOrder; import com.kangli.qms.service.exception.ExceptionService; import io.swagger.annotations.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;
@RestController @RequestMapping("/api/v1/quality-system") @Api(tags="体系管理") public class QualitySystemController{
 private final QualityObjectiveMapper objectives;private final InternalAuditPlanMapper audits;private final AuditNonconformityMapper nc;private final AdverseEventMapper events;private final CustomerFeedbackMapper feedbacks;private final MeasuringInstrumentMapper instruments;private final InstrumentLendingRecordMapper lendings;private final ExceptionService exceptionService;
 public QualitySystemController(QualityObjectiveMapper a,InternalAuditPlanMapper b,AuditNonconformityMapper c,AdverseEventMapper d,CustomerFeedbackMapper e,MeasuringInstrumentMapper f,InstrumentLendingRecordMapper g,ExceptionService h){objectives=a;audits=b;nc=c;events=d;feedbacks=e;instruments=f;lendings=g;exceptionService=h;}
 @GetMapping("/objectives") public R<List<QualityObjective>> objectives(){return R.ok(objectives.selectList(new LambdaQueryWrapper<QualityObjective>().eq(QualityObjective::getPlantCode,u().getPlantCode().name()).orderByDesc(QualityObjective::getCreatedAt)));}
 @PostMapping("/objectives") public R<QualityObjective> objective(@RequestBody QualityObjective x){set(x);if(x.getStatus()==null)x.setStatus("进行中");objectives.insert(x);return R.ok(x);}
 @PutMapping("/objectives/{id}") public R<QualityObjective> objectiveUpdate(@PathVariable Long id,@RequestBody QualityObjective x){QualityObjective old=objectives.selectById(id);if(old==null)throw bad("质量目标不存在");x.setId(id);x.setPlantCode(old.getPlantCode());x.setPlantName(old.getPlantName());x.setUpdatedBy(u().getRealName());objectives.updateById(x);return R.ok(objectives.selectById(id));}
 @GetMapping("/audits") public R<List<InternalAuditPlan>> audits(){return R.ok(audits.selectList(new LambdaQueryWrapper<InternalAuditPlan>().eq(InternalAuditPlan::getPlantCode,u().getPlantCode().name()).orderByDesc(InternalAuditPlan::getPlannedDate)));}
 @PostMapping("/audits") public R<InternalAuditPlan> audit(@RequestBody InternalAuditPlan x){set(x);if(x.getStatus()==null)x.setStatus("草稿");audits.insert(x);return R.ok(x);}
 @PutMapping("/audits/{id}") public R<InternalAuditPlan> auditUpdate(@PathVariable Long id,@RequestBody InternalAuditPlan x){InternalAuditPlan old=requireAudit(id);x.setId(id);x.setPlantCode(old.getPlantCode());x.setPlantName(old.getPlantName());x.setUpdatedBy(u().getRealName());audits.updateById(x);return R.ok(audits.selectById(id));}
 @PostMapping("/audits/{id}/transition") public R<InternalAuditPlan> auditTransition(@PathVariable Long id,@RequestParam String status,@RequestBody(required=false) InternalAuditPlan input){InternalAuditPlan x=requireAudit(id);List<String> allowed=Arrays.asList("待审批","已批准","实施中","已完成","取消");if(!allowed.contains(status))throw bad("内审状态不正确");if("已完成".equals(status)&&(input==null||input.getImplementationSummary()==null||input.getImplementationSummary().trim().isEmpty()))throw bad("请填写内审实施总结后再完成");x.setStatus(status);if(input!=null&&input.getImplementationSummary()!=null)x.setImplementationSummary(input.getImplementationSummary());x.setUpdatedBy(u().getRealName());audits.updateById(x);return R.ok(x);}
 @GetMapping("/nonconformities") public R<List<AuditNonconformity>> nonconformities(@RequestParam(required=false)Long auditPlanId){return R.ok(nc.selectList(new LambdaQueryWrapper<AuditNonconformity>().eq(AuditNonconformity::getPlantCode,u().getPlantCode().name()).eq(auditPlanId!=null,AuditNonconformity::getAuditPlanId,auditPlanId).orderByAsc(AuditNonconformity::getDueDate)));}
 @PostMapping("/nonconformities") public R<AuditNonconformity> nonconformity(@RequestBody AuditNonconformity x){set(x);if(x.getStatus()==null)x.setStatus("待整改");nc.insert(x);return R.ok(x);}
 @PutMapping("/nonconformities/{id}") public R<AuditNonconformity> nonconformityUpdate(@PathVariable Long id,@RequestBody AuditNonconformity input){AuditNonconformity x=requireNc(id);input.setId(id);input.setPlantCode(x.getPlantCode());input.setPlantName(x.getPlantName());input.setUpdatedBy(u().getRealName());nc.updateById(input);return R.ok(nc.selectById(id));}
 @PostMapping("/nonconformities/{id}/close") public R<AuditNonconformity> closeNc(@PathVariable Long id,@RequestBody AuditNonconformity input){AuditNonconformity x=nc.selectById(id);if(x==null)throw bad("不符合项不存在");if("严重".equals(x.getSeverity())&&(x.getCapaNo()==null||x.getCapaNo().trim().isEmpty()))throw bad("严重不符合项必须关联CAPA");if(input.getVerificationResult()==null||input.getVerificationResult().trim().isEmpty())throw bad("请填写验证结论");x.setRectificationMeasure(input.getRectificationMeasure());x.setVerificationResult(input.getVerificationResult());x.setStatus("已关闭");x.setUpdatedBy(u().getRealName());nc.updateById(x);return R.ok(x);}
 @GetMapping("/events") public R<List<AdverseEvent>> events(){return R.ok(events.selectList(new LambdaQueryWrapper<AdverseEvent>().eq(AdverseEvent::getPlantCode,u().getPlantCode().name()).orderByDesc(AdverseEvent::getEventDate)));}
 @PostMapping("/events") public R<AdverseEvent> event(@RequestBody AdverseEvent x){set(x);if(x.getStatus()==null)x.setStatus("待评估");events.insert(x);return R.ok(x);}
 @PutMapping("/events/{id}") public R<AdverseEvent> eventUpdate(@PathVariable Long id,@RequestBody AdverseEvent input){AdverseEvent x=requireEvent(id);input.setId(id);input.setPlantCode(x.getPlantCode());input.setPlantName(x.getPlantName());input.setUpdatedBy(u().getRealName());events.updateById(input);return R.ok(events.selectById(id));}
 @GetMapping("/feedback") public R<List<CustomerFeedback>> feedback(){return R.ok(feedbacks.selectList(new LambdaQueryWrapper<CustomerFeedback>().eq(CustomerFeedback::getPlantCode,u().getPlantCode().name()).orderByDesc(CustomerFeedback::getFeedbackDate)));}
 @PostMapping("/feedback") public R<CustomerFeedback> feedback(@RequestBody CustomerFeedback x){set(x);if(x.getStatus()==null)x.setStatus("待处理");feedbacks.insert(x);return R.ok(x);}
 @PutMapping("/feedback/{id}") public R<CustomerFeedback> feedbackUpdate(@PathVariable Long id,@RequestBody CustomerFeedback input){CustomerFeedback x=requireFeedback(id);input.setId(id);input.setPlantCode(x.getPlantCode());input.setPlantName(x.getPlantName());input.setUpdatedBy(u().getRealName());feedbacks.updateById(input);return R.ok(feedbacks.selectById(id));}
 @PostMapping("/feedback/{id}/close") public R<CustomerFeedback> closeFeedback(@PathVariable Long id,@RequestBody CustomerFeedback input){CustomerFeedback x=feedbacks.selectById(id);if(x==null)throw bad("顾客反馈不存在");if(input.getCustomerReply()==null||input.getCustomerReply().trim().isEmpty())throw bad("请填写客户回复内容");x.setInvestigation(input.getInvestigation());x.setHandlingMeasure(input.getHandlingMeasure());x.setCustomerReply(input.getCustomerReply());x.setStatus("已关闭");x.setUpdatedBy(u().getRealName());feedbacks.updateById(x);return R.ok(x);}
 @PostMapping("/{kind}/{id}/capa") public R<Map<String,Object>> createCapa(@PathVariable String kind,@PathVariable Long id){ExceptionOrder order=new ExceptionOrder();order.setSourceId(id);order.setProcessType("CAPA");order.setCapaStatus("待发起");order.setSeverity("一般");if("nonconformities".equals(kind)){AuditNonconformity x=requireNc(id);if(hasText(x.getCapaNo()))throw bad("该不符合项已关联CAPA");order.setSourceType("审核问题");order.setDefectDesc(x.getDescription());order.setSeverity("严重".equals(x.getSeverity())?"严重":"一般");ExceptionOrder created=exceptionService.create(order);x.setCapaNo(created.getExceptionNo());nc.updateById(x);return capaResult(created);}if("events".equals(kind)){AdverseEvent x=requireEvent(id);if(hasText(x.getCapaNo()))throw bad("该不良事件已关联CAPA");order.setSourceType("其他");order.setDefectDesc(x.getEventDescription());order.setSeverity(("死亡".equals(x.getHarmLevel())||"严重伤害".equals(x.getHarmLevel()))?"严重":"一般");ExceptionOrder created=exceptionService.create(order);x.setCapaNo(created.getExceptionNo());events.updateById(x);return capaResult(created);}if("feedback".equals(kind)){CustomerFeedback x=requireFeedback(id);if(hasText(x.getCapaNo()))throw bad("该顾客反馈已关联CAPA");order.setSourceType("客诉");order.setCustomerName(x.getCustomerName());order.setDefectDesc(x.getContent());ExceptionOrder created=exceptionService.create(order);x.setCapaNo(created.getExceptionNo());feedbacks.updateById(x);return capaResult(created);}throw bad("不支持的CAPA来源");}
 private R<Map<String,Object>> capaResult(ExceptionOrder x){Map<String,Object> r=new LinkedHashMap<>();r.put("exceptionId",x.getId());r.put("capaNo",x.getExceptionNo());return R.ok(r,"CAPA单已创建并回写编号");}
 @GetMapping("/dashboard") public R<Map<String,Object>> dashboard(){String p=u().getPlantCode().name();LocalDate today=LocalDate.now();List<QualityObjective> os=objectives.selectList(new LambdaQueryWrapper<QualityObjective>().eq(QualityObjective::getPlantCode,p));List<InternalAuditPlan> as=audits.selectList(new LambdaQueryWrapper<InternalAuditPlan>().eq(InternalAuditPlan::getPlantCode,p));List<AuditNonconformity> ns=nc.selectList(new LambdaQueryWrapper<AuditNonconformity>().eq(AuditNonconformity::getPlantCode,p));List<AdverseEvent> es=events.selectList(new LambdaQueryWrapper<AdverseEvent>().eq(AdverseEvent::getPlantCode,p));List<CustomerFeedback> fs=feedbacks.selectList(new LambdaQueryWrapper<CustomerFeedback>().eq(CustomerFeedback::getPlantCode,p));long under=os.stream().filter(x->x.getActualValue()!=null&&x.getTargetValue()!=null&&x.getActualValue().compareTo(x.getTargetValue())<0).count(),openNc=ns.stream().filter(x->!"已关闭".equals(x.getStatus())).count(),openEvents=es.stream().filter(x->!"已关闭".equals(x.getStatus())).count(),openFeedback=fs.stream().filter(x->!"已关闭".equals(x.getStatus())).count();List<Map<String,Object>> warnings=new ArrayList<>();for(MeasuringInstrument x:instruments.selectList(new LambdaQueryWrapper<MeasuringInstrument>().eq(MeasuringInstrument::getPlantCode,p).lt(MeasuringInstrument::getNextCalibrationDate,today).ne(MeasuringInstrument::getStatus,"已报废")))warnings.add(warning("计量校准超期",x.getInstrumentName(),x.getNextCalibrationDate(),x.getId(),"measurement"));for(InstrumentLendingRecord x:lendings.selectList(new LambdaQueryWrapper<InstrumentLendingRecord>().eq(InstrumentLendingRecord::getPlantCode,p).isNull(InstrumentLendingRecord::getReturnedAt).lt(InstrumentLendingRecord::getExpectedReturnDate,today)))warnings.add(warning("器具借用逾期",x.getBorrowerName(),x.getExpectedReturnDate(),x.getInstrumentId(),"measurement"));for(AuditNonconformity x:ns)if(!"已关闭".equals(x.getStatus())&&x.getDueDate()!=null&&x.getDueDate().isBefore(today))warnings.add(warning("不符合项逾期",x.getDescription(),x.getDueDate(),x.getId(),"nc"));for(AdverseEvent x:es)if(x.getReportDate()==null&&x.getReportDeadline()!=null&&!x.getReportDeadline().isAfter(today))warnings.add(warning("不良事件待上报",x.getEventDescription(),x.getReportDeadline(),x.getId(),"events"));for(CustomerFeedback x:fs)if(!"已关闭".equals(x.getStatus())&&x.getDueDate()!=null&&x.getDueDate().isBefore(today))warnings.add(warning("顾客反馈超时",x.getContent(),x.getDueDate(),x.getId(),"feedback"));warnings.sort(Comparator.comparing(x->String.valueOf(x.get("dueDate"))));Map<String,Long> eventTrend=monthly(es),feedbackTrend=monthlyFeedback(fs);Map<String,Object> r=new LinkedHashMap<>();r.put("objectiveTotal",os.size());r.put("underTarget",under);r.put("openNonconformities",openNc);r.put("openEvents",openEvents);r.put("openFeedback",openFeedback);r.put("auditCompletionRate",as.isEmpty()?0:Math.round(as.stream().filter(x->"已完成".equals(x.getStatus())).count()*1000.0/as.size())/10.0);r.put("capaLinked",ns.stream().filter(x->x.getCapaNo()!=null).count()+es.stream().filter(x->x.getCapaNo()!=null).count()+fs.stream().filter(x->x.getCapaNo()!=null).count());r.put("eventTrend",eventTrend);r.put("feedbackTrend",feedbackTrend);r.put("warnings",warnings);r.put("healthScore",Math.max(0,100-under*10-openNc*5-openEvents*8-openFeedback*4));return R.ok(r);}
 private Map<String,Object> warning(String type,String title,LocalDate due,Long id,String tab){Map<String,Object>x=new LinkedHashMap<>();x.put("type",type);x.put("title",title);x.put("dueDate",due);x.put("businessId",id);x.put("tab",tab);return x;}
 private Map<String,Long> monthly(List<AdverseEvent> list){Map<String,Long> r=new TreeMap<>();for(AdverseEvent x:list)if(x.getEventDate()!=null){String k=x.getEventDate().format(DateTimeFormatter.ofPattern("yyyy-MM"));r.put(k,r.getOrDefault(k,0L)+1);}return r;}
 private Map<String,Long> monthlyFeedback(List<CustomerFeedback> list){Map<String,Long> r=new TreeMap<>();for(CustomerFeedback x:list)if(x.getFeedbackDate()!=null){String k=x.getFeedbackDate().format(DateTimeFormatter.ofPattern("yyyy-MM"));r.put(k,r.getOrDefault(k,0L)+1);}return r;}
 private InternalAuditPlan requireAudit(Long id){InternalAuditPlan x=audits.selectById(id);if(x==null||!x.getPlantCode().equals(u().getPlantCode().name()))throw bad("内审计划不存在");return x;}private AuditNonconformity requireNc(Long id){AuditNonconformity x=nc.selectById(id);if(x==null||!x.getPlantCode().equals(u().getPlantCode().name()))throw bad("不符合项不存在");return x;}private AdverseEvent requireEvent(Long id){AdverseEvent x=events.selectById(id);if(x==null||!x.getPlantCode().equals(u().getPlantCode().name()))throw bad("不良事件不存在");return x;}private CustomerFeedback requireFeedback(Long id){CustomerFeedback x=feedbacks.selectById(id);if(x==null||!x.getPlantCode().equals(u().getPlantCode().name()))throw bad("顾客反馈不存在");return x;}
 private void set(Object x){LoginUser z=u();String code=z.getPlantCode().name(),name=z.getPlantCode().getChineseName(),by=z.getRealName();if(x instanceof QualityObjective){QualityObjective a=(QualityObjective)x;a.setPlantCode(code);a.setPlantName(name);a.setCreatedBy(by);a.setUpdatedBy(by);}else if(x instanceof InternalAuditPlan){InternalAuditPlan a=(InternalAuditPlan)x;a.setPlantCode(code);a.setPlantName(name);a.setCreatedBy(by);a.setUpdatedBy(by);}else if(x instanceof AuditNonconformity){AuditNonconformity a=(AuditNonconformity)x;a.setPlantCode(code);a.setPlantName(name);a.setCreatedBy(by);a.setUpdatedBy(by);}else if(x instanceof AdverseEvent){AdverseEvent a=(AdverseEvent)x;a.setPlantCode(code);a.setPlantName(name);a.setCreatedBy(by);a.setUpdatedBy(by);}else if(x instanceof CustomerFeedback){CustomerFeedback a=(CustomerFeedback)x;a.setPlantCode(code);a.setPlantName(name);a.setCreatedBy(by);a.setUpdatedBy(by);}}
 private boolean hasText(String x){return x!=null&&!x.trim().isEmpty();}private LoginUser u(){LoginUser z=LoginUserHolder.get();if(z==null||z.getPlantCode()==null)throw new BusinessException(ResultCode.UNAUTHORIZED,"未获取到登录用户信息");return z;}private BusinessException bad(String m){return new BusinessException(ResultCode.BAD_REQUEST,m);}
}
